                        data-testid={`favorite-note-${index}`}
                        className={noteClass}
                        value={metadata.notes[message.id!] ?? ""}
                        maxLength={1000}
                        disabled={saving}
                        onChange={(event) =>
                          setMetadata({
                            ...metadata,
                            notes: {
                              ...metadata.notes,
                              [message.id!]: event.target.value,
                            },
                          })
                        }
                      />
                    </label>
                  </details>
                </li>
              ))}
            </ol>
          </div>
          {alreadySaved && (
            <p role="status" className="text-sm text-muted-foreground">
              {t("messageFavorites.alreadySaved")}
            </p>
          )}
          {error && (
            <p role="alert" className="break-words text-sm text-destructive">
              {t("messageFavorites.saveFailed", { error })}
            </p>
          )}
          <div className="flex justify-end gap-2 border-t pt-3">
            <Button
              type="button"
              variant="ghost"
              disabled={saving}
              onClick={onClose}
            >
              {t("common.cancel")}
            </Button>
            <Button type="submit" disabled={saving} data-testid="favorite-save">
              {t(saving ? "messageFavorites.saving" : "common.save")}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
