    let cancelled = false;
    const { owner } = lease;
    if (owner && lease.current()) {
      void invoke<string>("owner_preview_lan_review", { owner, source }).then(
        (text) => {
          if (!cancelled && lease.current()) setPreview(text);
        },
        () => {
          if (!cancelled && lease.current()) setError("previewFailed");
        },
      );
    }
    return () => {
      cancelled = true;
      mounted.current = false;
    };
  }, [lease, source]);

  async function updateLink() {
    const { owner } = lease;
    if (inFlight.current || !owner || !lease.current() || preview === null) return;
    inFlight.current = true;
    setBusy(true);
    setError(null);
    try {
      if (url) {
        await invoke("owner_revoke_lan_review", { owner });
        if (lease.current() && mounted.current) onClose();
      } else {
        const result = await invoke<{ url: string }>("owner_start_lan_review", {
          owner,
          source,
          preview,
        });
        if (lease.current() && mounted.current) setUrl(result.url);
      }
    } catch {
      if (lease.current() && mounted.current) {
        setError(url ? "revokeFailed" : "startFailed");
      }
    } finally {
      inFlight.current = false;
      if (lease.current() && mounted.current) setBusy(false);
    }
  }

  async function copyLink() {
    if (!url || !lease.current()) return;
    try {
      await navigator.clipboard.writeText(url);
      if (lease.current() && mounted.current) {
        setCopied(true);
        setError(null);
      }
    } catch {
      if (lease.current() && mounted.current) setError("copyFailed");
    }
  }

  return (
    <Dialog open onOpenChange={(open) => {
      if (!open && !inFlight.current && !url) onClose();
    }}>
      <DialogContent data-testid="lan-review-dialog" hideClose={!!url || busy}>
        <DialogHeader>
          <DialogTitle>{t("lanReview.title")}</DialogTitle>
          <DialogDescription>{t(url ? "lanReview.activeHint" : "lanReview.exposure")}</DialogDescription>
        </DialogHeader>
        {url ? (
          <Input aria-label={t("lanReview.url")} readOnly value={url} onFocus={(event) => event.currentTarget.select()} />
        ) : preview !== null ? (
          <p className="max-h-[45dvh] overflow-y-auto whitespace-pre-wrap rounded-md border p-3 text-sm [overflow-wrap:anywhere]">{preview}</p>
        ) : !error ? (
          <p role="status" className="text-sm text-muted-foreground">{t("lanReview.loading")}</p>
        ) : null}
        {error && <p role="alert" className="text-sm text-destructive">{t(`lanReview.${error}`)}</p>}
        <div className="flex flex-wrap justify-end gap-2">
          {url ? (
            <Button variant="outline" disabled={busy} onClick={() => void copyLink()}>
              {t(copied ? "lanReview.copied" : "lanReview.copy")}
            </Button>
          ) : (
            <Button variant="ghost" disabled={busy} onClick={onClose}>{t("common.cancel")}</Button>
          )}
          <Button
            variant={url ? "destructive" : "default"}
            disabled={busy || preview === null}
            onClick={() => void updateLink()}
          >
            {t(url ? "lanReview.revoke" : "lanReview.create")}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
